(function (global) {
    function Chart(context, config) {
        this.ctx = context.getContext('2d');
        this.config = config || {};
        this.type = (config && config.type) || 'line';
        this.data = (config && config.data) || { labels: [], datasets: [] };
        this.options = (config && config.options) || {};
        this.draw();
    }

    Chart.prototype.draw = function () {
        const ctx = this.ctx;
        const canvas = ctx.canvas;
        const width = canvas.clientWidth || 300;
        const height = canvas.clientHeight || 200;
        canvas.width = width;
        canvas.height = height;
        ctx.clearRect(0, 0, width, height);

        if (this.type === 'line') {
            this.drawLineChart(width, height);
        } else if (this.type === 'bar') {
            this.drawBarChart(width, height);
        }
    };

    Chart.prototype.drawLineChart = function (width, height) {
        const ctx = this.ctx;
        const data = this.data.datasets[0].data || [];
        const max = Math.max(...data, 1);
        const padding = 24;
        const chartWidth = width - padding * 2;
        const chartHeight = height - padding * 2;
        ctx.strokeStyle = '#1a2736';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(padding, height - padding);
        ctx.lineTo(width - padding, height - padding);
        ctx.moveTo(padding, padding);
        ctx.lineTo(padding, height - padding);
        ctx.stroke();

        const gradient = ctx.createLinearGradient(0, 0, 0, height);
        gradient.addColorStop(0, 'rgba(255, 165, 2, 0.25)');
        gradient.addColorStop(1, 'rgba(255, 165, 2, 0)');
        ctx.beginPath();
        data.forEach((value, index) => {
            const x = padding + (index / Math.max(data.length - 1, 1)) * chartWidth;
            const y = height - padding - (value / max) * chartHeight;
            if (index === 0) {
                ctx.moveTo(x, y);
            } else {
                ctx.lineTo(x, y);
            }
        });
        const lastX = padding + ((data.length - 1) / Math.max(data.length - 1, 1)) * chartWidth;
        const lastY = height - padding - (data[data.length - 1] / max) * chartHeight;
        ctx.lineTo(lastX, height - padding);
        ctx.lineTo(padding, height - padding);
        ctx.closePath();
        ctx.fillStyle = gradient;
        ctx.fill();

        ctx.beginPath();
        data.forEach((value, index) => {
            const x = padding + (index / Math.max(data.length - 1, 1)) * chartWidth;
            const y = height - padding - (value / max) * chartHeight;
            if (index === 0) {
                ctx.moveTo(x, y);
            } else {
                ctx.lineTo(x, y);
            }
        });
        ctx.strokeStyle = '#ffa502';
        ctx.lineWidth = 2;
        ctx.stroke();
    };

    Chart.prototype.drawBarChart = function (width, height) {
        const ctx = this.ctx;
        const data = this.data.datasets[0].data || [];
        const max = Math.max(...data, 1);
        const padding = 24;
        const chartWidth = width - padding * 2;
        const chartHeight = height - padding * 2;
        const barWidth = chartWidth / data.length * 0.6;

        data.forEach((value, index) => {
            const x = padding + index * (chartWidth / data.length) + (chartWidth / data.length - barWidth) / 2;
            const barHeight = (value / max) * chartHeight;
            const y = height - padding - barHeight;
            ctx.fillStyle = '#ff4757';
            ctx.fillRect(x, y, barWidth, barHeight);
        });
    };

    Chart.prototype.update = function () {
        this.draw();
    };

    Chart.prototype.destroy = function () { };

    global.Chart = Chart;
})(window);
